public static String getRawValue(String propertyName){
  try {
    return getConfig().getRawValue(propertyName);
  } catch (NullPointerException e) {
    // 处理getConfig返回null的情况
    System.err.println("Configuration is not initialized: " + e.getMessage());
    return null;
  } catch (IllegalArgumentException e) {
    // 处理propertyName非法的情况
    System.err.println("Invalid property name: " + e.getMessage());
    return null;
  }
}
